import numpy as np
from sklearn.cluster import KMeans


def sk_kmeans_labels(X, k):
    labels = KMeans(n_clusters=k, n_init=10, random_state=0).fit_predict(X)
    order = {}
    out = []
    for lab in labels:
        if lab not in order:
            order[lab] = len(order)
        out.append(order[lab])
    return out
